(() => {
  'use strict';
  const sections={overview:['نمای کلی','home','آنچه امروز در ResumeIt می‌گذرد؛ از رشد کاربران تا استفاده و خرید.'],users:['کاربران','user','حساب‌ها، دسترسی‌ها و وضعیت فعالیت کاربران را مدیریت کنید.'],pages:['صفحات کاربران','globe','آدرس‌ها و وضعیت انتشار رزومه و صفحهٔ لینک‌ها.'],traffic:['بازدید و کلیک','chart','روند استفاده از صفحات عمومی در بازهٔ انتخاب‌شده.'],transactions:['کیف پول و تراکنش‌ها','card','گردش It، شارژهای مدیریتی و خریدهای انجام‌شده.'],purchases:['خریدها و اشتراک‌ها','star','دسترسی‌های خریداری‌شده و زمان پایان اشتراک‌ها.'],catalog:['قالب‌ها و فونت‌ها','palette','فهرست محصولات و قیمت‌های واقعی مورد استفاده در سایت.'],otp:['پیامک و OTP','phone','تعداد درخواست‌های ارسال، پذیرش سرویس پیامک و تأیید کدها.'],audit:['سابقهٔ مدیریت','history','عملیات مدیر همراه با دلیل، زمان و حساب هدف ثبت می‌شود.'],health:['وضعیت سرویس‌ها','settings','نسخهٔ سایت، اتصال سرویس‌ها و محدودیت‌های فعال.']};
  const section=document.body.dataset.section||'overview', $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fa=v=>Number(v||0).toLocaleString('fa-IR'),date=v=>v?new Date(typeof v==='string'&&!/^\d+$/.test(v)?v:Number(v)).toLocaleString('fa-IR',{dateStyle:'short',timeStyle:'short'}):'—',icon=n=>window.RI.icon(n),parse=v=>typeof v==='string'?JSON.parse(v):v;
  let page=1,rows=[],total=0,loadToken=0;
  const actionNames={credit:'شارژ کیف پول',suspend:'تعلیق حساب',restore:'رفع تعلیق', 'block-publication':'توقف انتشار','unblock-publication':'اجازهٔ انتشار','revoke-sessions':'خروج از همهٔ نشست‌ها'};
  const statuses={accepted:'پذیرفته‌شده',failed:'ارسال ناموفق',pending:'در انتظار نتیجه',register:'ثبت‌نام',login:'ورود',reset:'بازیابی رمز',phone:'تأیید شماره'};
  const badge=(s,label)=>'<span class="badge '+(s?'badge-success':'badge-warning')+'">'+esc(label|| (s?'فعال':'غیرفعال'))+'</span>';
  async function api(route,data){const response=await fetch('/api/admin/'+route,{cache:'no-store',method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(15000)});const result=await response.json();if(!response.ok){if(response.status===401)location.assign('/login/');throw new Error(result.error||'درخواست انجام نشد');}return result;}
  function summary(items){return '<dl class="summary-list">'+items.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+v+'</dd></div>').join('')+'</dl>';}
  function table(headers,data){return '<div class="table-scroll"><table class="table table-sm"><thead><tr>'+headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+data.map(row=>'<tr>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
  function chart(data,otp=false){const map=new Map();for(const r of data){const day=Number(r.day);if(!map.has(day))map.set(day,[0,0]);if(otp)map.set(day,[Number(r.accepted),Number(r.failed)]);else map.get(day)[r.event==='click'?1:0]+=Number(r.total);}const vals=[...map].sort((a,b)=>a[0]-b[0]),max=Math.max(1,...vals.flatMap(x=>x[1]));if(!vals.length)return '<p class="empty">هنوز آماری برای این بازه ثبت نشده است.</p>';return '<div class="chart" role="img" aria-label="'+(otp?'پذیرش و خطای ارسال OTP':'بازدید و کلیک صفحات')+'">'+vals.map(([day,[a,b]])=>'<div class="chart-day" title="'+esc(new Date(day*86400000).toLocaleDateString('fa-IR'))+'؛ '+fa(a)+' / '+fa(b)+'"><span style="height:'+Math.max(1,a/max*100)+'%"></span><span style="height:'+Math.max(1,b/max*100)+'%"></span></div>').join('')+'</div><div class="chart-legend"><span>'+(otp?'پذیرش سرویس':'بازدید')+'</span><span>'+(otp?'خطای ارسال':'کلیک')+'</span></div>';}
  function overview(d){const views=d.traffic.filter(r=>r.event!=='click').reduce((a,r)=>a+Number(r.total),0);return '<div class="overview-kpis">'+[[d.users.total,'کل کاربران',fa(d.users.recent)+' حساب جدید در بازه'],[views,'بازدید صفحات','در بازهٔ انتخاب‌شده'],[d.otp.accepted,'ارسال پذیرفته‌شدهٔ OTP',fa(d.otp.failed)+' ارسال ناموفق'],[Number(d.purchases.spent)/2000,'خرید با It',fa(d.purchases.total)+' تراکنش خرید']].map(([v,k,sub])=>'<div class="kpi"><span>'+k+'</span><strong>'+fa(v)+'</strong><small>'+sub+'</small></div>').join('')+'</div><div class="admin-grid"><section class="panel"><h2>روند بازدید و کلیک</h2>'+chart(d.traffic)+'</section><section class="panel"><h2>وضعیت حساب‌ها و صفحات</h2>'+summary([['شماره‌های تأییدشده',fa(d.users.verified)],['کاربران دارای نشست فعال',fa(d.sessions.total)],['رزومه‌های منتشرشده',fa(d.pages.resumes)],['صفحه‌های لینک منتشرشده',fa(d.pages.links)],['اشتراک‌های فعال',fa(d.subscriptions.total)],['موجودی کل کیف پول‌ها',fa(Number(d.wallet.balance)/2000)+' It']])+'</section><section class="panel"><h2>ارسال پیامک</h2>'+chart(d.otpDaily,true)+'</section><section class="panel"><h2>تأیید و کنترل دسترسی</h2>'+summary([['درخواست ارسال در بازه',fa(d.otp.total)],['کدهای تأییدشده',fa(d.otp.verified)],['حساب‌های محدودشده',fa(d.controls.suspended)],['شروع داده‌های OTP در بازه',date(d.otp.started)]])+'<p class="notice">پذیرش سرویس به معنی تحویل به گوشی نیست. آمار ماندگار OTP از نسخهٔ ۲۱ ثبت می‌شود.</p></section></div>';}
  const userLink=(id,name)=>'<a href="/admin/users/?user='+encodeURIComponent(id)+'">'+esc(name||'مشاهدهٔ حساب')+'</a>';
  function publication(v){const p=parse(v)||{};return 'رزومه: '+(p.resume?.status==='published'?'منتشرشده':'پیش‌نویس')+' / لینک: '+(p.links?.status==='published'?'منتشرشده':'پیش‌نویس');}
  function listContent(kind,data){
    const configs={users:[['کاربر','شماره','وضعیت','موجودی It','تاریخ عضویت','جزئیات'],r=>[userLink(r.id,[r.first_name,r.last_name].filter(Boolean).join(' ')||r.name||'بدون نام'),'<span class="ltr">'+esc(r.phone||'ورود اجتماعی')+'</span>',r.suspended?badge(false,'تعلیق‌شده'):badge(true,r.is_admin?'مدیر':'فعال'),fa(Number(r.balance_units)/2000),date(r.created_at),userLink(r.id)]],pages:[['مالک','آدرس','انتشار','کنترل انتشار','ویرایش'],r=>[userLink(r.id,r.name),r.slug?'<a class="ltr" href="https://'+esc(r.slug)+'.resumeit.ir" target="_blank" rel="noopener">'+esc(r.slug)+'.resumeit.ir</a>':'بدون آدرس',esc(publication(r.pub)),badge(!r.publication_blocked,r.publication_blocked?'متوقف‌شده':'مجاز'),fa(r.revision)]],transactions:[['مالک','عنوان','تغییر It','موجودی پس از تراکنش','زمان'],r=>[userLink(r.user_id,r.name||r.phone),esc(r.label),fa(Number(r.delta_units)/2000),fa(Number(r.balance_units)/2000),date(r.created_at)]],purchases:[['مالک','محصول','قیمت It','نوع دسترسی','زمان خرید'],r=>[userLink(r.user_id,r.name||r.phone),esc(r.ref),fa(Number(r.price_units)/2000),r.expires_at?'اشتراک تا '+date(r.expires_at):'خرید یک‌باره',date(r.created_at)]],otp:[['شماره','کاربرد','نتیجهٔ ارسال','زمان درخواست','تأیید کد'],r=>['<span class="ltr">'+esc(r.phone)+'</span>',esc(statuses[r.purpose]||r.purpose),badge(r.status==='accepted',statuses[r.status]||r.status),date(r.created_at),date(r.verified_at)]],audit:[['مدیر','عملیات','حساب هدف','دلیل','زمان'],r=>[esc(r.name||r.actor_id),esc(actionNames[r.action]||r.action),userLink(r.target_id),esc(r.reason),date(r.created_at)]]};
    const otpSummary=kind==='otp'&&data.stats?'<div class="overview-kpis">'+[['accepted','پذیرفته‌شده'],['failed','ناموفق'],['pending','در انتظار نتیجه'],['verified','کد تأییدشده']].map(([key,label])=>'<div class="kpi"><span>'+label+'</span><strong>'+fa(data.stats[key])+'</strong><small>با فیلتر انتخاب‌شده</small></div>').join('')+'</div><p class="notice">ثبت ماندگار از نسخهٔ ۲۱ شروع شده است. کد پیامک ذخیره یا نمایش داده نمی‌شود و پذیرش سرویس، تحویل به گوشی را اثبات نمی‌کند.</p>':'';
    const [headers,mapper]=configs[kind];return otpSummary+'<section class="panel">'+(!data.rows.length?'<div class="empty">موردی با این فیلتر پیدا نشد. بازه یا عبارت جست‌وجو را تغییر دهید.</div>':table(headers,data.rows.map(mapper)))+'<div class="pager"><span>'+fa(data.total)+' مورد · صفحهٔ '+fa(data.page)+' از '+fa(Math.max(1,Math.ceil(data.total/25)))+'</span><div><button class="btn" id="prev" '+(page===1?'disabled':'')+'>قبلی</button><button class="btn" id="next" '+(page*25>=data.total?'disabled':'')+'>بعدی</button></div></div></section>';
  }
  function detail(d){const u=d.user;return '<div class="admin-grid"><section class="panel"><h2>'+esc([u.first_name,u.last_name].filter(Boolean).join(' ')||u.name||'حساب بدون نام')+'</h2>'+summary([['شماره','<span class="ltr">'+esc(u.phone||'—')+'</span>'],['تأیید شماره',badge(u.phone_verified)],['نقش',u.is_admin?'مدیر':'کاربر'],['وضعیت',badge(!u.suspended,u.suspended?'تعلیق‌شده':'فعال')],['تاریخ عضویت',date(u.created_at)],['موجودی',fa(Number(d.balance_units)/2000)+' It'],['نشست‌های فعال',fa(d.sessions.total)],['ورود اجتماعی',esc(d.social.map(x=>x.provider).join('، ')||'ندارد')]])+'<div class="detail-actions">'+[['credit','شارژ کیف پول'],['revoke-sessions','خروج نشست‌ها'],...(!u.is_admin?[[u.suspended?'restore':'suspend',u.suspended?'رفع تعلیق':'تعلیق حساب'],[u.publication_blocked?'unblock-publication':'block-publication',u.publication_blocked?'اجازهٔ انتشار':'توقف انتشار']]:[])].map(([action,label])=>'<button class="btn '+(action==='credit'?'btn-primary':'')+'" data-action="'+action+'" data-user="'+esc(u.id)+'">'+label+'</button>').join('')+'</div></section><section class="panel"><h2>صفحه و دسترسی‌های کاربر</h2>'+summary([['آدرس',esc(d.document?.slug||'انتخاب نشده')],['وضعیت انتشار',esc(d.document?publication(d.document.pub):'صفحه ساخته نشده')],['قالب رزومه',esc(d.document?.template||'—')],['تعداد دسترسی‌ها',fa(d.access.length)]])+(d.access.length?table(['محصول','پایان دسترسی'],d.access.map(a=>[esc(a.ref),date(a.expires_at)||'دائمی'])):'')+'</section></div><p class="notice">تغییرات مدیریتی به همراه دلیل ثبت می‌شوند. تعلیق، نشست‌ها را می‌بندد و نمایش عمومی را متوقف می‌کند؛ محتوای کاربر حذف نمی‌شود.</p>';}
  function catalog(d){const group=$('#catalog-kind').value,items=group==='plans'?Object.entries(d.plans).map(([id,v])=>({id,...v})):d[group];return '<div class="catalog-grid">'+items.map(x=>'<article class="catalog-item">'+(['vista','satiar'].includes(x.id)?'<img src="/brand/template-'+x.id+'-thumb.png" alt="نمای قالب '+esc(x.name)+'" loading="lazy">':'')+'<h2>'+esc(x.name||x.id)+'</h2><p>'+esc(x.desc||x.description||x.id)+'</p>'+summary([['قیمت',x.price?fa(x.price)+' تومان / '+fa(x.price/2000)+' It':'رایگان'],['شناسه',esc(x.id)],['دسترسی',esc(x.access|| (x.months?'اشتراک':'رایگان'))]])+'</article>').join('')+'</div><p class="notice">قیمت‌ها از همان فهرست فعال سایت خوانده می‌شوند. تغییر فهرست محصولات در این نسخه با انتشار کد انجام می‌شود تا قرارداد قالب‌ها و قیمت خرید یکسان بماند.</p>';}
  function health(d){return '<div class="admin-grid"><section class="panel"><h2>سرویس‌های فعال</h2>'+summary([['پایگاه داده',badge(true,d.database)],['پیامک SMS.ir',badge(d.smsConfigured,d.smsConfigured?'پیکربندی‌شده':'تنظیم نشده')],['ورود گوگل',badge(d.googleConfigured,d.googleConfigured?'پیکربندی‌شده':'تنظیم نشده')],['ورود گیت‌هاب',badge(d.githubConfigured,d.githubConfigured?'پیکربندی‌شده':'تنظیم نشده')],['درگاه پرداخت','فعلاً فعال نیست'],['دامنه',esc(d.origin)]])+'</section><section class="panel"><h2>نسخه و محدودیت‌ها</h2>'+summary([['نسخه','<span class="ltr">'+esc(d.version)+'</span>'],['زمان فعالیت سرور',fa(Math.floor(d.uptime/60000))+' دقیقه'],['سقف روزانهٔ OTP',fa(d.limits.otpDaily)],['سقف روزانهٔ هر شماره',fa(d.limits.phoneDaily)],['فاصلهٔ ارسال مجدد',fa(d.limits.resendSeconds)+' ثانیه'],['اعتبار کد',fa(d.limits.otpSeconds)+' ثانیه']])+'</section></div><p class="notice">پیکربندی‌شده بودن، سلامت لحظه‌ای سرویس یا تحویل پیامک را تضمین نمی‌کند. کلیدها و رمزهای سرویس‌ها در این پنل نمایش داده نمی‌شوند.</p>';}
  async function load(){const token=++loadToken;$('#content').setAttribute('aria-busy','true');$('#content').innerHTML='<div class="loading" role="status">در حال دریافت اطلاعات…</div>';$('#refresh').disabled=true;$('#export').disabled=true;try{const detailId=new URL(location.href).searchParams.get('user');let route=section==='traffic'?'overview':section;if(section==='users'&&detailId){if(!/^[a-f0-9-]{36}$/.test(detailId))throw new Error('شناسهٔ حساب معتبر نیست');route='users/'+detailId;}const params=new URLSearchParams({page,days:$('#days').value,q:$('#search').value,status:$('#status').value}),d=await api(route+'?'+params);if(token!==loadToken)return;rows=d.rows||[];total=d.total||0;$('#content').innerHTML=section==='overview'?overview(d):section==='traffic'?'<section class="panel"><h2>روند بازدید صفحات</h2>'+chart(d.traffic)+table(['تاریخ','نوع','تعداد'],d.traffic.map(r=>[new Date(Number(r.day)*86400000).toLocaleDateString('fa-IR'),esc(r.event),fa(r.total)]))+'</section>':section==='catalog'?catalog(d):section==='health'?health(d):detailId&&section==='users'?detail(d):listContent(section,d);$('#updated').textContent='آخرین دریافت: '+date(Date.now());$('#export').disabled=!rows.length;}catch(e){if(token===loadToken)$('#content').innerHTML='<div class="notice error" role="alert">'+esc(e.message)+' <button class="btn" id="retry">تلاش دوباره</button></div>';}finally{if(token===loadToken){$('#content').removeAttribute('aria-busy');$('#refresh').disabled=false;}}}
  function actionDialog(id,action){const dlg=$('#action-dialog');$('#action-title').textContent=actionNames[action];$('#action-explain').textContent='این عملیات روی حساب انتخاب‌شده انجام می‌شود و در سابقهٔ مدیریت باقی می‌ماند.';$('#amount-field').hidden=action!=='credit';$('#amount').required=action==='credit';$('#action-error').textContent='';$('#reason').value='';$('#amount').value='';const requestId=crypto.randomUUID().replace(/-/g,'');let pending=false;$('#action-form').onsubmit=async e=>{e.preventDefault();if(pending)return;pending=true;$('#action-submit').disabled=true;$('#action-cancel').disabled=true;try{const reason=$('#reason').value.trim(),toman=Number($('#amount').value);await api('users/'+id+'/actions',{action,reason,requestId,...(action==='credit'?{toman}:{})});dlg.close();await load();}catch(error){$('#action-error').textContent=error.message;}finally{pending=false;$('#action-submit').disabled=false;$('#action-cancel').disabled=false;}};dlg.oncancel=e=>{if(pending)e.preventDefault();};$('#action-cancel').onclick=()=>dlg.close();dlg.showModal();}
  function exportCsv(){const keys=Object.keys(rows[0]||{}),cell=v=>'"'+String(typeof v==='object'?JSON.stringify(v):v??'').replace(/^[\s]*[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"',csv='\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='resumeit-'+section+'-page-'+page+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function boot(){const response=await fetch('/api/auth/session',{cache:'no-store'}),{user}=await response.json();if(!user){location.replace('/login/');return;}if(!user.is_admin){location.replace('/dashboard/');return;}const info=sections[section];$('#page-title').textContent=info[0];$('#page-desc').textContent=info[2];$('#section-title').textContent=info[0];$('#admin-name').textContent=[user.first_name,user.last_name].filter(Boolean).join(' ')||'مدیر ResumeIt';$('#admin-nav').innerHTML=Object.entries(sections).map(([id,[title,ic]])=>'<a href="'+(id==='overview'?'/admin/':'/admin/'+id+'/')+'" '+(id===section?'aria-current="page"':'')+'>'+icon(ic)+'<span>'+title+'</span></a>').join('');$('#admin-menu').innerHTML=icon('menu');$('#search-wrap').hidden=!['users','pages','transactions','purchases','otp','audit'].includes(section);$('#days-wrap').hidden=['users','pages','catalog','health'].includes(section);$('#status-wrap').hidden=!['users','otp'].includes(section);$('#status').innerHTML='<option value="">همهٔ وضعیت‌ها</option>'+(section==='users'?'<option value="active">فعال</option><option value="suspended">تعلیق‌شده</option>':'<option value="accepted">پذیرفته‌شده</option><option value="failed">ناموفق</option><option value="pending">در انتظار</option>');$('#catalog-controls').hidden=section!=='catalog';$('#export').hidden=['overview','traffic','catalog','health'].includes(section);if(new URL(location.href).searchParams.has('user')){$('#filters').hidden=true;$('#export').hidden=true;}$('#refresh').onclick=load;$('#filters').onsubmit=e=>{e.preventDefault();page=1;load();};$('#days').onchange=()=>{page=1;load();};$('#status').onchange=()=>{page=1;load();};$('#catalog-kind').onchange=load;$('#export').onclick=exportCsv;document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)actionDialog(a.dataset.user,a.dataset.action);if(e.target.closest('#prev')){page--;load();}if(e.target.closest('#next')){page++;load();}if(e.target.closest('#retry'))load();});const drawer=open=>{$('#admin-side').dataset.open=open;$('#admin-backdrop').dataset.open=open;$('#admin-menu').setAttribute('aria-expanded',String(open));};$('#admin-menu').onclick=()=>drawer($('#admin-side').dataset.open!=='true');$('#admin-backdrop').onclick=()=>drawer(false);document.addEventListener('keydown',e=>{if(e.key==='Escape')drawer(false);});$('#user-panel').onclick=()=>{sessionStorage.setItem('ri-panel-choice',user.id);};$('#logout').onclick=async()=>{try{const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw new Error();sessionStorage.removeItem('ri-panel-choice');location.assign('/login/');}catch{$('#content').innerHTML='<p class="notice error" role="alert">خروج انجام نشد؛ دوباره تلاش کنید.</p>';}};await load();}
  boot().catch(()=>{$('#content').innerHTML='<p class="notice error">پنل آماده نشد؛ صفحه را دوباره باز کنید.</p>';});
})();
